exercise.description:
Даны длины трёх отрезков. Напечатайте одно из слов:

- `не существует` — если невырожденный треугольник сложить нельзя;
- `равносторонний` — все стороны равны;
- `равнобедренный` — равны ровно две стороны;
- `разносторонний` — все стороны разные.

exercise.starterCode:
#include <stdio.h>

int main(void) {
    // Напишите решение здесь.
    return 0;
}

exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    long long a, b, c;
    scanf("%lld %lld %lld", &a, &b, &c);
    if (a >= b + c || b >= a + c || c >= a + b) {
        printf("не существует\n");
    } else if (a == b && b == c) {
        printf("равносторонний\n");
    } else if (a == b || b == c || a == c) {
        printf("равнобедренный\n");
    } else {
        printf("разносторонний\n");
    }
    return 0;
}

