#include <stdio.h>
#include <math.h>

int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    int d = b * b - 4 * a * c;
    if (d < 0) {
        printf("0\n");
    } else if (d == 0) {
        double x = -b / (2.0 * a) + 0.0;
        printf("1 %.3f\n", x);
    } else {
        double r = sqrt(d);
        double x1 = (-b - r) / (2.0 * a) + 0.0;
        double x2 = (-b + r) / (2.0 * a) + 0.0;
        if (x1 > x2) {
            double t = x1;
            x1 = x2;
            x2 = t;
        }
        printf("2 %.3f %.3f\n", x1, x2);
    }
    return 0;
}

