additionalExercises.referenceSolution:
#include <stdio.h>

int main(void) {
    int km, hour;
    scanf("%d %d", &km, &hour);
    long long cost = 100;
    if (km > 20) {
        cost += 17 * 30 + (long long)(km - 20) * 20;
    } else if (km > 3) {
        cost += (long long)(km - 3) * 30;
    }
    if (hour <= 5) {
        cost = cost * 3 / 2;
    }
    printf("%lld\n", cost);
    return 0;
}

