#include <stdio.h>

int main(void) {
    int d, m, y;
    scanf("%d.%d.%d", &d, &m, &y);
    int leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    int length = 31;
    if (m == 4 || m == 6 || m == 9 || m == 11) {
        length = 30;
    } else if (m == 2) {
        length = leap ? 29 : 28;
    }
    if (d < length) {
        d++;
    } else {
        d = 1;
        if (m < 12) {
            m++;
        } else {
            m = 1;
            y++;
        }
    }
    printf("%02d.%02d.%04d\n", d, m, y);
    return 0;
}

